import json,glob,unicodedata,re
nomi="""Albinea|Albonese|Ameglia|Arcola|Arenzano|Bagnolo San Vito|Baiso|Baricella|Bentivoglio|Bolano|Bomporto|Borgo Val di Taro|Cadeo|Campagnola Emilia|Campogalliano|Carpi|Casalgrande|Casarza Ligure|Castel Goffredo|Castel di Casio|Castelbelforte|Castelnuovo Magra|Castelvetro di Modena|Castiglione Chiavarese|Castiglione d'Adda|Correggio|Cura Carpignano|Dosolo|Dozza|Empoli|Farini|Figline e Incisa Valdarno|Finale Emilia|Forte dei Marmi|Fucecchio|Galliera|Gazzola|Gazzuolo|Gravellona Lomellina|Gualtieri|Lodi|Loreo|Luni|Masi Torello|Moglia|Monsummano Terme|Montodine|Ostiglia|Quattro Castella|Reggiolo|Ricengo|Roncoferraro|Rosolina|Rottofreno|Sala Baganza|Sambuca Pistoiese|San Bellino|San Felice sul Panaro|San Giovanni in Croce|San Secondo Parmense|Sant'Agata Bolognese|Sant'Ilario d'Enza|Scandicci|Sermide e Felonica|Silvano Pietra|Solignano|Somaglia|Taglio di Po|Tizzano Val Parma|Traversetolo|Vaiano Cremasco|Varsi|Zola Predosa|Felino|Luzzara|Adria|Reggio nell'Emilia|Forlimpopoli|Misano Adriatico|Montale""".split('|')
ISP=set(['Albinea', 'Albonese', 'Ameglia', 'Arcola', 'Arenzano', 'Bagnolo San Vito', 'Baiso', 'Baricella', 'Bentivoglio', 'Bolano', 'Bomporto', 'Borgo Val di Taro', 'Cadeo', 'Campagnola Emilia', 'Campogalliano', 'Carpi', 'Casalgrande', 'Casarza Ligure', 'Castel Goffredo', 'Castel di Casio', 'Castelbelforte', 'Castelnuovo Magra', 'Castelvetro di Modena', 'Castiglione Chiavarese', "Castiglione d'Adda", 'Correggio', 'Cura Carpignano', 'Dosolo', 'Dozza', 'Empoli', 'Farini', 'Figline e Incisa Valdarno', 'Finale Emilia', 'Forte dei Marmi', 'Fucecchio', 'Galliera', 'Gazzola', 'Gazzuolo', 'Gravellona Lomellina', 'Gualtieri', 'Lodi', 'Loreo', 'Luni', 'Masi Torello', 'Moglia', 'Monsummano Terme', 'Montodine', 'Ostiglia', 'Quattro Castella', 'Reggiolo', 'Ricengo', 'Roncoferraro', 'Rosolina', 'Rottofreno', 'Sala Baganza', 'Sambuca Pistoiese', 'San Bellino', 'San Felice sul Panaro', 'San Giovanni in Croce', 'San Secondo Parmense', "Sant'Agata Bolognese", "Sant'Ilario d'Enza", 'Scandicci', 'Sermide e Felonica', 'Silvano Pietra', 'Solignano', 'Somaglia', 'Taglio di Po', 'Tizzano Val Parma', 'Traversetolo', 'Vaiano Cremasco', 'Varsi', 'Zola Predosa', 'Felino', 'Luzzara']);MAN=set(['Reggiolo', 'Monsummano Terme', 'Traversetolo', 'Varsi', 'Cura Carpignano', 'Gazzuolo', 'Sala Baganza', 'Fucecchio', 'Correggio', 'Felino', 'Castel Goffredo', 'Quattro Castella', 'Empoli', 'Montodine', 'Luni', 'Albonese', 'Castelnuovo Magra', 'Dozza', 'Baiso', 'Moglia', 'Adria', "Reggio nell'Emilia", 'Bagnolo San Vito', 'Forlimpopoli', 'Solignano', 'Casalgrande', 'Carpi', 'Scandicci', 'Finale Emilia', 'Baricella', 'Misano Adriatico', 'Bentivoglio', 'Montale', 'Castel di Casio', "Sant'Ilario d'Enza", 'Figline e Incisa Valdarno'])
def k(s): s=unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower(); return re.sub(r'[^a-z]','',s)
geo=json.load(open(glob.glob('/tmp/geo/node_modules/italian-cap-comuni-province/dist/gi_comuni_cap*.json')[0]))
pop={k(c['nome']):c.get('popolazione') for c in json.load(open('/tmp/geo/node_modules/comuni-json/comuni.json'))}
idx={}
for g in geo: idx.setdefault(k(g['denominazione_ita']),g)
out=[];manca=[]
for n in nomi:
    g=idx.get(k(n))
    if not g: manca.append(n);continue
    out.append(dict(s=('I' if n in ISP else '')+('M' if n in MAN else ''),n=g['denominazione_ita'],pr=g['sigla_provincia'],reg=g['denominazione_regione'],lat=float(g['lat']),lon=float(g['lon']),pop=pop.get(k(g['denominazione_ita']))))
print(len(out),'trovati; mancano:',manca)
print([ (o['n'],o['pop']) for o in out if not o['pop']])
json.dump(out,open('/tmp/gen/comuni-serviti.json','w'),ensure_ascii=False)
print(min(o['lat'] for o in out),max(o['lat'] for o in out),min(o['lon'] for o in out),max(o['lon'] for o in out))
